   Design tokens — dark theme
   ===================================================== */
:root {
  --bg-page:        #0f1117;
  --bg-card:        #1a1d27;
  --bg-input:       #242736;
  --bg-input-focus: #2c3047;
  --border:         #3a3f5c;
  --border-focus:   #6c8ef7;
  --border-error:   #f87171;
  --border-success: #4ade80;

  --text-primary:   #e8eaf6;
  --text-secondary: #9097b8;
  --text-label:     #c5c9e0;
  --text-error:     #fca5a5;
  --text-success:   #86efac;
  --text-helper:    #8a91b4;

  --accent:         #6c8ef7;
  --accent-hover:   #8aa8ff;
  --accent-active:  #5070d6;

  --radius-sm:  6px;
  --radius-md:  10px;
  --radius-lg:  16px;

  --shadow-card: 0 4px 32px rgba(0, 0, 0, 0.5);
  --shadow-input-focus: 0 0 0 3px rgba(108, 142, 247, 0.30);
  --shadow-input-error: 0 0 0 3px rgba(248, 113, 113, 0.25);

  --transition: 160ms ease;
}

/* =====================================================
   Reset / base
   ===================================================== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
}

body {
  background-color: var(--bg-page);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
}

/* =====================================================
   Skip link
   ===================================================== */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top var(--transition);
}

.skip-link:focus {
  top: 1rem;
}

/* =====================================================
   Page layout
   ===================================================== */
main {
  width: 100%;
  max-width: 520px;
}

/* =====================================================
   Card
   ===================================================== */
.form-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
  box-shadow: var(--shadow-card);
}

/* =====================================================
   Headings
   ===================================================== */
.form-card h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.25rem;
  line-height: 1.3;
}

.form-card .form-subtitle {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  margin-bottom: 1.75rem;
}

/* =====================================================
   Required field legend
   ===================================================== */
.required-legend {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  margin-bottom: 1.5rem;
}

.required-legend .required-marker {
  color: #f87171;
  font-weight: 700;
  margin-right: 0.25em;
  aria-hidden: true; /* decorative duplicate; screen reader text is next */
}

/* =====================================================
   Form fields
   ===================================================== */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  margin-bottom: 1.25rem;
}

.form-field:last-of-type {
  margin-bottom: 1.75rem;
}

/* Label */
.form-field label {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-label);
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.form-field label .required-star {
  color: #f87171;
  font-weight: 700;
  line-height: 1;
}

/* Input */
.form-field input {
  background: var(--bg-input);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 1rem;
  font-family: inherit;
  padding: 0.625rem 0.875rem;
  width: 100%;
  transition: border-color var(--transition), box-shadow var(--transition), background var(--transition);
  outline: none;
}

.form-field input::placeholder {
  color: var(--text-helper);
}

.form-field input:hover:not(:disabled) {
  border-color: #5a6080;
}

.form-field input:focus {
  background: var(--bg-input-focus);
  border-color: var(--border-focus);
  box-shadow: var(--shadow-input-focus);
}

/* Valid state */
.form-field input.is-valid {
  border-color: var(--border-success);
}

/* Invalid / error state */
.form-field input[aria-invalid="true"] {
  border-color: var(--border-error);
  box-shadow: var(--shadow-input-error);
}

/* Helper text */
.field-help {
  font-size: 0.8125rem;
  color: var(--text-helper);
  line-height: 1.5;
}

/* Error message */
.field-error {
  font-size: 0.8125rem;
  color: var(--text-error);
  line-height: 1.5;
  display: none; /* hidden until triggered */
}

.field-error.visible {
  display: block;
}

/* =====================================================
   Submit button
   ===================================================== */
.btn-submit {
  display: block;
  width: 100%;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  padding: 0.75rem 1.5rem;
  cursor: pointer;
  letter-spacing: 0.01em;
  transition: background var(--transition), transform 80ms ease, box-shadow var(--transition);
}

.btn-submit:hover {
  background: var(--accent-hover);
}

.btn-submit:active {
  background: var(--accent-active);
  transform: translateY(1px);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--border-focus);
  outline-offset: 3px;
}

/* =====================================================
   Status / success banner
   ===================================================== */
.form-status {
  margin-top: 1.25rem;
  border-radius: var(--radius-sm);
  padding: 0.75rem 1rem;
  font-size: 0.9375rem;
  line-height: 1.5;
  min-height: 1.5em; /* keep in layout so live region persists */
}

.form-status:empty {
  padding: 0;
  margin: 0;
}

.form-status.success {
  background: rgba(74, 222, 128, 0.12);
  border: 1px solid var(--border-success);
  color: var(--text-success);
}

.form-status.error-summary {
  background: rgba(248, 113, 113, 0.10);
  border: 1px solid var(--border-error);
  color: var(--text-error);
}

/* =====================================================
   Forced-colors / high-contrast support
   ===================================================== */
@media (forced-colors: active) {
  .form-field input:focus {
    outline: 2px solid ButtonText;
    box-shadow: none;
  }

  .form-field input[aria-invalid="true"] {
    outline: 2px solid Mark;
    box-shadow: none;
  }

  .btn-submit:focus-visible {
    outline: 2px solid ButtonText;
  }
}

/* =====================================================
   Reflow — 320 px
   ===================================================== */
@media (max-width: 360px) {
  .form-card {
    padding: 1.5rem 1rem;
    border-radius: var(--radius-md);
  }
}

/* =====================================================
   Reduced motion
   ===================================================== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0ms !important;
  }
}
