 * Contact form — inline validation + accessible error handling
 *
 * Rules:
 * - Validate on blur (after first interaction) and on submit.
 * - On submit with errors, focus the first invalid field.
 * - Errors use aria-invalid + aria-describedby; cleared when fixed.
 * - Status region pre-exists in DOM; only its text is mutated.
 */

(function () {
  'use strict';

  const form = document.getElementById('contact-form');
  const statusEl = document.getElementById('form-status');

  // Track which fields have been "touched" (blurred at least once)
  const touched = new Set();

  /* --------------------------------------------------
     Validation rules
  -------------------------------------------------- */
  const validators = {
    fullname: (val) => {
      if (!val.trim()) return 'Error: Full name is required.';
      if (val.trim().length < 2) return 'Error: Enter at least 2 characters.';
      return null;
    },
    email: (val) => {
      if (!val.trim()) return 'Error: Email address is required.';
      // RFC-5321 inspired, practical pattern
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(val.trim())) {
        return 'Error: Enter a valid email address, e.g. name@example.com.';
      }
      return null;
    },
    phone: (val) => {
      if (!val.trim()) return null; // optional
      // Allow digits, spaces, hyphens, dots, parens, leading +
      if (!/^\+?[\d\s\-().]{7,20}$/.test(val.trim())) {
        return 'Error: Enter a valid phone number, e.g. +1 (555) 123-4567.';
      }
      return null;
    },
  };

  /* --------------------------------------------------
     Apply / clear error on a field
  -------------------------------------------------- */
  function applyError(fieldId, message) {
    const input = document.getElementById(fieldId);
    const errorEl = document.getElementById(fieldId + '-error');

    if (message) {
      input.setAttribute('aria-invalid', 'true');
      input.classList.remove('is-valid');
      errorEl.textContent = message;
      errorEl.classList.add('visible');
    } else {
      input.removeAttribute('aria-invalid');
      input.classList.add('is-valid');
      errorEl.textContent = '';
      errorEl.classList.remove('visible');
    }
  }

  /* --------------------------------------------------
     Validate a single field (returns error string | null)
  -------------------------------------------------- */
  function validateField(fieldId) {
    const input = document.getElementById(fieldId);
    const validate = validators[fieldId];
    if (!validate) return null;
    const error = validate(input.value);
    applyError(fieldId, error);
    return error;
  }

  /* --------------------------------------------------
     Blur — validate only touched fields
  -------------------------------------------------- */
  ['fullname', 'email', 'phone'].forEach((id) => {
    const input = document.getElementById(id);

    input.addEventListener('blur', () => {
      touched.add(id);
      validateField(id);
    });

    // Re-validate on input so errors clear as the user types
    input.addEventListener('input', () => {
      if (touched.has(id)) validateField(id);
    });
  });

  /* --------------------------------------------------
     Submit
  -------------------------------------------------- */
  form.addEventListener('submit', (e) => {
    e.preventDefault();

    // Mark all fields touched and validate
    const fieldIds = ['fullname', 'email', 'phone'];
    const errors = fieldIds.map((id) => {
      touched.add(id);
      return validateField(id);
    });

    const firstErrorIndex = errors.findIndex((err) => err !== null);

    if (firstErrorIndex !== -1) {
      // Clear any previous success status
      setStatus('', '');

      // Focus first invalid field
      document.getElementById(fieldIds[firstErrorIndex]).focus();
      return;
    }

    // All valid — simulate submission
    setStatus(
      'Your message has been sent. We'll be in touch soon.',
      'success'
    );

    // Reset form and validation state
    form.reset();
    fieldIds.forEach((id) => {
      touched.delete(id);
      applyError(id, null);
      document.getElementById(id).classList.remove('is-valid');
    });
  });

  /* --------------------------------------------------
     Mutate the live-region status element
  -------------------------------------------------- */
  function setStatus(message, type) {
    statusEl.textContent = '';
    statusEl.className = 'form-status';
    if (message) {
      statusEl.textContent = message;
      if (type) statusEl.classList.add(type);
    }
  }
})();
