          />
          <span id="email-error" class="field-error" aria-live="polite"></span>
        </div>

        <!-- Phone Number (optional) -->
        <div class="form-field">
          <label for="phone">Phone number</label>
          <input
            id="phone"
            name="phone"
            type="tel"
            autocomplete="tel"
            aria-describedby="phone-help phone-error"
            placeholder="+1 (555) 123-4567"
          />
          <span id="phone-help" class="field-help">
            Optional. Include country code if outside the US,
            e.g.&nbsp;+44&nbsp;7700&nbsp;900123. Digits, spaces,
            hyphens, and parentheses are accepted.
          </span>
          <span id="phone-error" class="field-error" aria-live="polite"></span>
        </div>

        <button type="submit" class="btn-submit">Send message</button>
      </form>

      <!--
        Live region pre-exists in DOM; text mutated by JS.
