            name="fullname"
            type="text"
            required
            autocomplete="name"
            aria-describedby="fullname-error"
            placeholder="Jane Smith"
          />
          <span id="fullname-error" class="field-error" aria-live="polite"></span>
        </div>

        <!-- Email Address -->
        <div class="form-field">
          <label for="email">
            Email address
            <span class="required-star" aria-hidden="true">*</span>
            <span class="sr-only">(required)</span>
          </label>
          <input
            id="email"
            name="email"
            type="email"
