          <span id="email-error" class="field-error" aria-live="polite"></span>
        </div>

        <!-- Phone Number (optional) -->
        <div class="form-field">
          <label for="phone">Phone number</label>
          <input
            id="phone"
            name="phone"
            type="tel"
            autocomplete="tel"
            aria-describedby="phone-help phone-error"
            placeholder="+1 (555) 123-4567"
          />
          <span id="phone-help" class="field-help">
            Optional. Include country code if outside the US,
            e.g.&nbsp;+44&nbsp;7700&nbsp;900123. Digits, spaces,
            hyphens, and parentheses are accepted.
          </span>
          <span id="phone-error" class="field-error" aria-live="polite"></span>
        </div>

        <button type="submit" class="btn-submit">Send message</button>
      </form>

      <!--
        Live region pre-exists in DOM; text mutated by JS.
        role="status" = polite + atomic, used for success.
      -->
      <div id="form-status" class="form-status" role="status"></div>
    </div>
  </main>

  <script>
(function () {
  'use strict';

  const form = document.getElementById('contact-form');
  const statusEl = document.getElementById('form-status');

  // Track which fields have been "touched" (blurred at least once)
  const touched = new Set();

  /* --------------------------------------------------
     Validation rules
  -------------------------------------------------- */
  const validators = {
    fullname: (val) => {
      if (!val.trim()) return 'Error: Full name is required.';
      if (val.trim().length < 2) return 'Error: Enter at least 2 characters.';
      return null;
    },
    email: (val) => {
      if (!val.trim()) return 'Error: Email address is required.';
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(val.trim())) {
        return 'Error: Enter a valid email address, e.g. name@example.com.';
      }
      return null;
    },
    phone: (val) => {
      if (!val.trim()) return null; // optional
      if (!/^\+?[\d\s\-().]{7,20}$/.test(val.trim())) {
        return 'Error: Enter a valid phone number, e.g. +1 (555) 123-4567.';
      }
      return null;
    },
  };

  /* --------------------------------------------------
     Apply / clear error on a field
  -------------------------------------------------- */
  function applyError(fieldId, message) {
    const input = document.getElementById(fieldId);
    const errorEl = document.getElementById(fieldId + '-error');

    if (message) {
      input.setAttribute('aria-invalid', 'true');
      input.classList.remove('is-valid');
      errorEl.textContent = message;
      errorEl.classList.add('visible');
    } else {
      input.removeAttribute('aria-invalid');
      input.classList.add('is-valid');
      errorEl.textContent = '';
      errorEl.classList.remove('visible');
    }
  }

  /* --------------------------------------------------
     Validate a single field (returns error string | null)
  -------------------------------------------------- */
  function validateField(fieldId) {
    const input = document.getElementById(fieldId);
    const validate = validators[fieldId];
    if (!validate) return null;
    const error = validate(input.value);
    applyError(fieldId, error);
    return error;
  }

  /* --------------------------------------------------
     Blur — validate only touched fields
  -------------------------------------------------- */
  ['fullname', 'email', 'phone'].forEach((id) => {
    const input = document.getElementById(id);

    input.addEventListener('blur', () => {
      touched.add(id);
      validateField(id);
    });

