     Mutate the live-region status element
  -------------------------------------------------- */
  function setStatus(message, type) {
    statusEl.textContent = '';
    statusEl.className = 'form-status';
    if (message) {
      statusEl.textContent = message;
      if (type) statusEl.classList.add(type);
    }
  }
